<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const player = { x: 100, y: 100 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x, player.y, 20, 20);
        }

        function drawTiles() {
            for (const tile in tiles) {
                const { crop, stage } = tiles[tile];
                ctx.fillStyle = crop === 'seed' ? 'red' : 'green';
                ctx.fillRect(tile.split(',')[0], tile.split(',')[1], 20, 20);
            }
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.font = '16px Arial';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 30);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 50);
        }

        function drawDay() {
            ctx.fillStyle = 'purple';
            ctx.font = '16px Arial';
            ctx.fillText(`Day: ${day}`, 10, 70);
        }

        function update() {
            drawPlayer();
            drawTiles();
            drawInventory();
            drawDay();
            requestAnimationFrame(update);
        }

        document.addEventListener('keydown', (e) => {
            switch (e.key) {
                case 'ArrowUp':
                    player.y -= 10;
                    break;
                case 'ArrowDown':
                    player.y += 10;
                    break;
                case 'ArrowLeft':
                    player.x -= 10;
                    break;
                case 'ArrowRight':
                    player.x += 10;
                    break;
                case 'p':
                    if (inventory.seeds > 0) {
                        tiles[player.x.toString() + ',' + player.y.toString()] = { crop: 'seed', stage: 0 };
                        inventory.seeds--;
                    }
                    break;
                case 't':
                    day++;
                    break;
                case 'h':
                    if (tiles[player.x.toString() + ',' + player.y.toString()].crop === 'seed') {
                        tiles[player.x.toString() + ',' + player.y.toString()] = { crop: 'crops', stage: 0 };
                        inventory.crops++;
                        inventory.seeds--;
                    }
                    break;
                case 's':
                    localStorage.setItem('gameState', JSON.stringify({ player, tiles, inventory, day }));
                    break;
                case 'l':
                    const savedState = localStorage.getItem('gameState');
                    if (savedState) {
                        const { player, tiles, inventory, day } = JSON.parse(savedState);
                        window.game = { player, tiles, inventory, day };
                    }
                    break;
            }
        });

        update();
    </script>
</body>
</html>
